css:
.impactsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #29362b;
    background: linear-gradient(160deg, #f4f1e8 0%, #eaf0e3 100%);
    border-radius: 18px;
}

.impactsim-container * {
    box-sizing: border-box;
}

.impactsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f5135 0%, #2f6e44 55%, #5b8c4e 100%);
    color: #f6faf2;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 81, 53, 0.30);
}

.impactsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.impactsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #d6ecc6;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.impactsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7f2dc;
}

.impactsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c4a33;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.impactsim-period-counter #currentDay,
.impactsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f5135;
}

.impactsim-round-name {
    background: #dcebcd;
    color: #1f5135;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.impactsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b14;
    background: #f7e3d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.impactsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.impactsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0e6d4;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
    border-top: 4px solid #5b8c4e;
}

.impactsim-card-sales { border-top-color: #2f6e44; }
.impactsim-card-cred { border-top-color: #b8862b; }
.impactsim-card-risk { border-top-color: #b04a2f; }
.impactsim-card-budget { border-top-color: #4a6f8c; }

.impactsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7a64;
}

.impactsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f5135;
}

.impactsim-card-sales .impactsim-value { color: #2f6e44; }
.impactsim-card-cred .impactsim-value { color: #b8862b; }
.impactsim-card-risk .impactsim-value { color: #b04a2f; }
.impactsim-card-budget .impactsim-value { color: #4a6f8c; }

.impactsim-sublabel {
    font-size: 0.76rem;
    color: #7c8a72;
    line-height: 1.35;
}

.impactsim-sales-hit .impactsim-value { color: #2f6e44; }
.impactsim-sales-miss .impactsim-value { color: #b04a2f; }

.impactsim-cred-crash .impactsim-value { color: #b04a2f; }

.impactsim-risk-danger { border-top-color: #b04a2f; }
.impactsim-risk-danger .impactsim-value { color: #b04a2f; }
.impactsim-risk-safe .impactsim-value { color: #2f6e44; }

.impactsim-budget-over { border-top-color: #b04a2f; }
.impactsim-budget-over .impactsim-value { color: #b04a2f; }

.impactsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f5135;
    color: #eef6e6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.impactsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.impactsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #5b8c4e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.05);
}

.impactsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.impactsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5135;
    margin-bottom: 6px;
}

.impactsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #38463a;
}

.impactsim-briefing-text strong { color: #2f6e44; }
.impactsim-briefing-text em { color: #9a3b14; font-style: italic; }

.impactsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0e6d4;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
}

.impactsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5135;
    border-bottom: 2px solid #e8eede;
    padding-bottom: 8px;
}

.impactsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4a33;
    margin: 14px 0 6px;
}

.impactsim-container select,
.impactsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c7d2b8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8faf3;
    color: #29362b;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.impactsim-container select:focus,
.impactsim-container input[type="number"]:focus {
    outline: none;
    border-color: #5b8c4e;
    box-shadow: 0 0 0 3px rgba(91, 140, 78, 0.18);
}

.impactsim-container select option {
    background-color: #ffffff;
    color: #29362b;
}

.impactsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #5b8c4e;
}

.impactsim-range-readout,
.impactsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f6e44;
    margin-top: 4px;
}

.impactsim-range-readout span:nth-child(2),
.impactsim-alloc-readout span:nth-child(2) {
    color: #b8862b;
    font-weight: 800;
}

.impactsim-hint {
    font-size: 0.8rem;
    color: #7c8a72;
    margin-top: 4px;
    line-height: 1.4;
}

.impactsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.impactsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f7ec;
    border: 1px solid #dde7cf;
    border-radius: 9px;
    padding: 8px 12px;
}

.impactsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4a33;
}

.impactsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.impactsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.impactsim-container .btn-primary {
    background: linear-gradient(135deg, #2f6e44 0%, #5b8c4e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 110, 68, 0.28);
}

.impactsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.impactsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c7d2b8;
    color: #6c7a64;
}

.impactsim-coach {
    background: #1f5135;
    color: #eef6e6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 81, 53, 0.22);
}

.impactsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #a9d28c;
    margin-bottom: 8px;
}

.impactsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.impactsim-coach-body strong { color: #f2d488; }
.impactsim-coach-body em { color: #f3b59a; font-style: italic; }

.impactsim-history,
.impactsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0e6d4;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
}

.impactsim-history h3,
.impactsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5135;
}

.impactsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4a33;
}

.impactsim-container table#usfHistoryTable th {
    background: #eaf0e1;
    color: #1f5135;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d7e2c8;
}

.impactsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef3e7;
}

.impactsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8faf3;
}

.impactsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .impactsim-container {
        padding: 14px;
    }
    .impactsim-header h1 {
        font-size: 1.7rem;
    }
    .impactsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .impactsim-value {
        font-size: 2rem;
    }
    .impactsim-clock {
        margin-left: 0;
    }
    .impactsim-period-counter {
        font-size: 0.88rem;
    }
    .impactsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .impactsim-alloc-row {
        flex-wrap: wrap;
    }
    .impactsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .impactsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

