(function() {
    'use strict';

    class ImpactAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Marketing for Impact`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Botané SAS).
            this.START_CRED = 71;        // 'buy because of values' segment, %
            this.START_RISK = 12;        // greenwashing risk, low headroom
            this.MANDATE = 18;           // board target +18% revenue
            this.MISS_FLOOR = 13;        // miss by >5pts (below 13) reopens a down-round
            this.BUDGET_CAP = 3.2;       // EUR 3.2M campaign budget
            this.MAX_FINE_PCT = 0.80;    // fine up to 80% of campaign spend
            this.RISK_FLOOR = 5;         // claims always carry some latent exposure
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    salesLift: 0,
                    credibility: this.START_CRED,
                    gwRisk: this.START_RISK,
                    budgetUsed: 0,
                    proofReserve: 0,        // EUR M ring-fenced for substantiation in R1
                    cobrandTax: 0,          // margin/control drag if eco-label accepted
                    accused: false,         // watchdog challenge landed in R4
                    fined: false,
                    overBudget: false,
                    salesHistory: [0],
                    credHistory: [this.START_CRED],
                    riskHistory: [this.START_RISK],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    // Seeded defaults are a plausible-but-middling campaign — deliberately NOT the
                    // textbook-best set, so a pure click-through does NOT auto-win. It under-funds
                    // proof, leans mass-heavy, borrows no credibility, and only partially withdraws.
                    // R1 — moderate, under-funded proof.
                    climate: `condition`,
                    fragile: `qualify`,
                    proof: 0.15,
                    // R2 — mass-dominant mix (owned share ~0.27) + safest listing.
                    mass: 1.3,
                    social: 0.9,
                    owned: 0.8,
                    listing: `terms`,
                    // R3 — declines the influencer (safe) but borrows no eco-label credibility,
                    // and a middling pre-draft.
                    influencer: `decline`,
                    cobrand: `decline`,
                    ngo: `disclose`,
                    defence: 50,
                    // R4 — partial withdrawal: limits damage but is not the decisive recovery.
                    response: `partial`,
                    holding: `evidence`,
                    governance: `adhoc`,
                    discipline: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cl = document.getElementById(`climateInput`);
                const fr = document.getElementById(`fragileInput`);
                const pr = document.getElementById(`proofInput`);
                if (cl) decisions.climate = cl.value;
                if (fr) decisions.fragile = fr.value;
                if (pr) decisions.proof = parseFloat(pr.value);
                if (!Number.isFinite(decisions.proof) || decisions.proof < 0 || decisions.proof > 0.8) {
                    warn(`warn_proof_range`); return false;
                }
            } else if (round === 2) {
                const ma = document.getElementById(`massInput`);
                const so = document.getElementById(`socialInput`);
                const ow = document.getElementById(`ownedInput`);
                const li = document.getElementById(`listingInput`);
                if (ma) decisions.mass = parseFloat(ma.value);
                if (so) decisions.social = parseFloat(so.value);
                if (ow) decisions.owned = parseFloat(ow.value);
                if (li) decisions.listing = li.value;
                const parts = [decisions.mass, decisions.social, decisions.owned];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_channel_negative`); return false;
                }
                // Budget left after the R1 substantiation reserve.
                const left = Math.round((this.BUDGET_CAP - (state.domainState.proofReserve || 0)) * 100) / 100;
                const total = Math.round((decisions.mass + decisions.social + decisions.owned) * 100) / 100;
                if (total > left + 0.001) {
                    warn(`warn_channel_total`); return false;
                }
            } else if (round === 3) {
                const inf = document.getElementById(`influencerInput`);
                const cob = document.getElementById(`cobrandInput`);
                const ngo = document.getElementById(`ngoInput`);
                const df = document.getElementById(`defenceInput`);
                if (inf) decisions.influencer = inf.value;
                if (cob) decisions.cobrand = cob.value;
                if (ngo) decisions.ngo = ngo.value;
                if (df) decisions.defence = parseInt(df.value, 10);
                if (!Number.isFinite(decisions.defence) || decisions.defence < 0 || decisions.defence > 100) {
                    warn(`warn_defence_range`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`responseInput`);
                const ho = document.getElementById(`holdingInput`);
                const go = document.getElementById(`governanceInput`);
                const di = document.getElementById(`disciplineInput`);
                if (re) decisions.response = re.value;
                if (ho) decisions.holding = ho.value;
                if (go) decisions.governance = go.value;
                if (di) decisions.discipline = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.discipline) || decisions.discipline < 0 || decisions.discipline > 100) {
                    warn(`warn_discipline_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // salesDelta = revenue lift this round; credDelta = values-segment credibility;
            // riskDelta = greenwashing exposure (lower is safer); spend in EUR M.
            let salesDelta = 0, credDelta = 0, riskDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Audit the claims: conditional-with-proof on the flagship, qualify the absolutes.
                switch (d.climate) {
                    case `condition`: credDelta += 4; riskDelta += 4; salesDelta += 2; coachKey = `coach_r1_condition`; break;
                    case `defensible`: credDelta += 1; riskDelta += 22; salesDelta += 4; coachKey = `coach_r1_defensible`; break;
                    case `drop`: credDelta -= 4; riskDelta -= 4; salesDelta -= 3; coachKey = `coach_r1_drop`; break;
                }
                switch (d.fragile) {
                    case `qualify`: credDelta += 5; riskDelta -= 5; salesDelta += 2; coachKey = (d.climate === `condition`) ? `coach_r1_sharp` : coachKey; break;
                    case `keep`: credDelta -= 6; riskDelta += 20; salesDelta += 3; coachKey = `coach_r1_keep`; break;
                    case `dropall`: credDelta -= 8; riskDelta -= 3; salesDelta -= 4; coachKey = `coach_r1_dropall`; break;
                }
                // Ring-fence proof now: this reserve is what makes a R4 substantiation possible.
                spend += d.proof;
                ds.proofReserve = d.proof;
                if (d.proof >= 0.3) { credDelta += 3; riskDelta -= 6; }
                else if (d.proof >= 0.15) { credDelta += 1; riskDelta -= 2; }
                else { riskDelta += 4; if (d.climate === `condition`) coachKey = `coach_r1_noproof`; }

                summaryKey = (d.climate === `condition` && d.fragile === `qualify` && d.proof >= 0.3) ? `sum_r1_good`
                    : ((d.climate === `defensible` || d.fragile === `keep`) ? `sum_r1_max`
                    : ((d.climate === `drop` && d.fragile === `dropall`) ? `sum_r1_bland` : `sum_r1_weak`));
            } else if (round === 2) {
                spend += (d.mass + d.social + d.owned);
                const channelTotal = d.mass + d.social + d.owned || 0.0001;
                const ownedShare = d.owned / channelTotal;
                const massShare = (d.mass + d.social) / channelTotal;

                // Mass reach buys fast lift but amplifies any fragile claim already in the mix.
                // The amplification multiplies whatever greenwashing risk the claim set carries.
                salesDelta += d.mass * 5.0 + d.social * 4.2 + d.owned * 3.0;
                const riskBase = ds.gwRisk; // current risk from R1 claim choices
                riskDelta += (massShare * (riskBase * 0.18)) + d.social * 2.2;
                riskDelta -= d.owned * 1.5;

                // Owned/earned protects and builds credibility; pure mass thins it.
                if (ownedShare >= 0.45) { credDelta += 6; coachKey = `coach_r2_owned`; }
                else if (ownedShare >= 0.30) { credDelta += 2; coachKey = `coach_r2_balanced`; }
                else { credDelta -= 5; coachKey = `coach_r2_mass`; }

                // The supermarket listing decision — a brand-claim choice, not just a price choice.
                switch (d.listing) {
                    case `terms`: salesDelta += 3; credDelta += 2; coachKey = (ownedShare >= 0.30) ? `coach_r2_listterms` : coachKey; break;
                    case `concede`: salesDelta += 6; credDelta -= 9; riskDelta += 12; coachKey = `coach_r2_concede`; break;
                    case `decline`: salesDelta -= 2; credDelta += 2; coachKey = `coach_r2_decline`; break;
                }

                summaryKey = (ownedShare >= 0.40 && d.listing !== `concede`) ? `sum_r2_good`
                    : (d.listing === `concede` ? `sum_r2_concede`
                    : (massShare >= 0.75 ? `sum_r2_mass` : `sum_r2_weak`));
            } else if (round === 3) {
                // Borrowed vs built credibility — reach without fit rents a gap you can't back.
                switch (d.influencer) {
                    case `decline`: credDelta += 3; coachKey = `coach_r3_infldecline`; break;
                    case `accept`: salesDelta += 2; credDelta -= 15; riskDelta += 8; coachKey = `coach_r3_inflaccept`; break;
                    case `microswap`: salesDelta += 2; credDelta += 6; coachKey = `coach_r3_microswap`; break;
                }
                // Eco-label co-brand: instant credibility, but 30% control/margin tax dampens later lift.
                switch (d.cobrand) {
                    case `accept`: credDelta += 6; riskDelta -= 4; salesDelta += 2; ds.cobrandTax = 1; coachKey = (d.influencer === `decline` || d.influencer === `microswap`) ? `coach_r3_cobrand` : coachKey; break;
                    case `decline`: salesDelta += 1; break;
                }
                // NGO transparency demand: imperfect-but-disclosed beats perfect-but-secret.
                switch (d.ngo) {
                    case `disclose`: credDelta += 8; riskDelta -= 7; coachKey = `coach_r3_disclose`; break;
                    case `declinequiet`: credDelta -= 14; riskDelta += 9; coachKey = `coach_r3_decline`; break;
                }
                // A proof-led pre-drafted defence lowers the damage when the challenge lands in R4.
                if (d.defence >= 70) { riskDelta -= 6; credDelta += 2; }
                else if (d.defence <= 30) { riskDelta += 5; coachKey = `coach_r3_spin`; }

                summaryKey = (d.influencer !== `accept` && d.ngo === `disclose`) ? `sum_r3_good`
                    : (d.influencer === `accept` ? `sum_r3_rent`
                    : (d.ngo === `declinequiet` ? `sum_r3_secret` : `sum_r3_weak`));
            } else if (round === 4) {
                // The claim is challenged. The watchdog's 72-hour stress-test SURFACES latent risk:
                // a campaign that never funded its proof has an exposure the launch hid until now.
                // This is what finally separates a proof-led plan from a lucky-looking one.
                ds.accused = true;

                // You can only substantiate if you actually ring-fenced the proof in R1.
                const hasProof = (ds.proofReserve >= 0.3);
                const proofGap = Math.max(0, 0.4 - ds.proofReserve);   // unfunded substantiation (EUR M)
                riskDelta += proofGap * 30;                            // surfaced exposure: up to +12
                if (!hasProof) coachKey = `coach_r4_surfaced`;

                let resolveRisk = 0; // how much this response neutralises standing risk

                switch (d.response) {
                    case `substantiate`:
                        if (hasProof) { resolveRisk = 0.80; credDelta += 9; salesDelta += 4; coachKey = `coach_r4_substantiate`; }
                        else { resolveRisk = 0.15; credDelta -= 14; riskDelta += 6; salesDelta -= 4; coachKey = `coach_r4_nosub`; }
                        break;
                    case `reframe`:
                        resolveRisk = 0.70; credDelta += 6; salesDelta -= 1; coachKey = `coach_r4_reframe`; break;
                    case `partial`:
                        resolveRisk = 0.45; credDelta += 1; salesDelta -= 3; coachKey = `coach_r4_partial`; break;
                    case `defend`:
                        resolveRisk = 0.05; credDelta -= 16; salesDelta -= 2; coachKey = `coach_r4_defend`; break;
                    case `fullpull`:
                        resolveRisk = 0.95; credDelta -= 3; salesDelta -= 12; coachKey = `coach_r4_fullpull`; break;
                }

                // Holding statement: answer an evidence question with evidence, not spin.
                switch (d.holding) {
                    case `evidence`: credDelta += 4; resolveRisk += 0.10; break;
                    case `commitment`: credDelta -= 10; resolveRisk -= 0.15; coachKey = `coach_r4_pr`; break;
                    case `nocomment`: credDelta -= 5; resolveRisk -= 0.05; break;
                }

                // Standing claim-governance — does this prevent the next incident?
                switch (d.governance) {
                    case `owned`: credDelta += 4; riskDelta -= 5; break;
                    case `adhoc`: credDelta += 1; break;
                    case `none`: credDelta -= 4; riskDelta += 4; break;
                }

                // Apply the risk resolution against the standing greenwashing risk.
                resolveRisk = Math.max(0, Math.min(1, resolveRisk + (d.discipline - 50) / 200));
                riskDelta -= ds.gwRisk * resolveRisk;

                // Fine: if risk is still high after the response, the DGCCRF can act — up to 80% of spend.
                const projectedRisk = Math.max(0, Math.min(100, ds.gwRisk + riskDelta));
                if (projectedRisk >= 55) {
                    ds.fined = true;
                    const fine = Math.round(ds.budgetUsed * this.MAX_FINE_PCT * 100) / 100;
                    spend += fine;
                    salesDelta -= 6;
                    credDelta -= 8;
                    coachKey = `coach_r4_fined`;
                }

                summaryKey = (d.response === `substantiate` && hasProof && d.holding === `evidence`) ? `sum_r4_substantiate`
                    : (d.response === `reframe` && d.holding === `evidence`) ? `sum_r4_reframe`
                    : (d.response === `defend` || (d.response === `substantiate` && !hasProof)) ? `sum_r4_bad`
                    : (d.response === `fullpull`) ? `sum_r4_pull` : `sum_r4_weak`;
            }

            // Resource accounting (EUR M, two decimals).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.overBudget = true;

            // KPIs move on their deltas, with the eco-label control tax dampening upside lift.
            if (ds.cobrandTax && salesDelta > 0) salesDelta *= 0.85;
            ds.salesLift = Math.round((ds.salesLift + salesDelta) * 10) / 10;
            ds.salesLift = Math.max(-20, Math.min(40, ds.salesLift));

            // Credibility (the values segment) has diminishing returns above its 71 baseline —
            // you cannot easily push perceived authenticity toward 100, but it can crash fast.
            // This keeps headroom on the meter through the final round so no good lever saturates.
            if (credDelta > 0) {
                const head = Math.max(0, 92 - ds.credibility); // soft ceiling at 92
                credDelta = credDelta * (head / (head + 14));
            }
            ds.credibility = Math.max(0, Math.min(100, Math.round((ds.credibility + credDelta) * 10) / 10));

            // Greenwashing risk: a residual floor — claims always carry some latent exposure —
            // and full headroom upward so every fragile choice still registers in the final round.
            ds.gwRisk = Math.round((ds.gwRisk + riskDelta) * 10) / 10;
            ds.gwRisk = Math.max(this.RISK_FLOOR, Math.min(100, ds.gwRisk));

            ds.salesHistory.push(Math.round(ds.salesLift * 10) / 10);
            ds.credHistory.push(Math.round(ds.credibility));
            ds.riskHistory.push(Math.round(ds.gwRisk));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                salesLift: Math.round(ds.salesLift * 10) / 10,
                salesDelta: Math.round(salesDelta * 10) / 10,
                credibility: Math.round(ds.credibility),
                credDelta: Math.round(credDelta),
                gwRisk: Math.round(ds.gwRisk),
                riskDelta: Math.round(riskDelta),
                budgetUsed: ds.budgetUsed,
                fined: ds.fined,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoneyM(v, lang) {
            const n = Math.round(Number(v) * 10) / 10;
            if (lang === `es`) {
                return n.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + n.toFixed(1) + `M`;
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`salesDisplay`, `domainState.salesLift`, (v) => {
                const card = document.querySelector(`.impactsim-card-sales`);
                if (card) {
                    card.classList.toggle(`impactsim-sales-hit`, Number(v) >= self.MANDATE - 5);
                    card.classList.toggle(`impactsim-sales-miss`, Number(v) < self.MISS_FLOOR);
                }
                const n = Math.round(Number(v) * 10) / 10;
                return (n >= 0 ? `+` : ``) + n.toFixed(1) + `%`;
            });
            uiManager.bind(`credDisplay`, `domainState.credibility`, (v) => {
                const card = document.querySelector(`.impactsim-card-cred`);
                if (card) card.classList.toggle(`impactsim-cred-crash`, Number(v) < self.START_CRED - 18);
                return Math.round(Number(v));
            });
            uiManager.bind(`riskDisplay`, `domainState.gwRisk`, (v) => {
                const card = document.querySelector(`.impactsim-card-risk`);
                if (card) {
                    card.classList.toggle(`impactsim-risk-danger`, Number(v) >= 55);
                    card.classList.toggle(`impactsim-risk-safe`, Number(v) < 25);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.impactsim-card-budget`);
                if (card) card.classList.toggle(`impactsim-budget-over`, Number(v) > self.BUDGET_CAP + 0.001);
                return self._fmtMoneyM(v, window.mySimulation.language);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const lang = window.mySimulation.language;
                const used = self._fmtMoneyM(v, lang);
                const cap = self._fmtMoneyM(self.BUDGET_CAP, lang);
                return used + ` / ` + cap;
            });

            // Proof slider readout (R1).
            const pr = document.getElementById(`proofInput`);
            const prReadout = document.getElementById(`proofReadout`);
            if (pr && prReadout) {
                const setpr = () => { prReadout.textContent = (parseFloat(pr.value) || 0).toFixed(2); };
                setpr();
                pr.addEventListener(`input`, setpr);
            }

            // Defence slider readout (R3).
            const df = document.getElementById(`defenceInput`);
            const dfReadout = document.getElementById(`defenceReadout`);
            if (df && dfReadout) {
                dfReadout.textContent = df.value;
                df.addEventListener(`input`, () => { dfReadout.textContent = df.value; });
            }

            // Channel-spend live total (R2).
            const chIds = [`massInput`, `socialInput`, `ownedInput`];
            const spendReadout = document.getElementById(`spendReadout`);
            const recompute = function() {
                let total = 0;
                chIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (spendReadout) spendReadout.textContent = total.toFixed(2);
                const left = Math.round((self.BUDGET_CAP - (window.mySimulation.state.domainState.proofReserve || 0)) * 100) / 100;
                const bar = document.querySelector(`.impactsim-alloc-readout`);
                if (bar) bar.style.color = (total > left + 0.001) ? `#b04a2f` : ``;
            };
            chIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

