        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.credHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                impactChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.salesHistory },
                        { data: ds.credHistory },
                        { data: ds.riskHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const sales = Math.round(ds.salesLift * 10) / 10;
            const cred = Math.round(ds.credibility);
            const risk = Math.round(ds.gwRisk);

            const hitMandate = sales >= this.MANDATE - 5;     // within 5pts of +18%
            const credIntact = cred >= this.START_CRED - 8;   // values segment held
            const safe = risk < 35 && !ds.fined;
            // Composite: growth, credibility, and (inverted) risk — credibility is the engine.
            const composite = Math.round(
                Math.max(0, Math.min(100, (sales + 20) / 40 * 100)) * 0.30 +
                cred * 0.40 +
                (100 - risk) * 0.30
            );

            // 'Authentic Growth' is the exemplar tier: it requires the full textbook play —
            // strong composite, near-floor greenwashing risk (proof funded or cleanly reframed,
            // not merely partially patched), AND a genuinely intact values segment (no rented
            // credibility, no withheld disclosure). A competent click-through lands 'Credible Campaign'.
            const exemplar = composite >= 92 && risk <= 8 && cred >= 86;

            let performanceKey = `credibility_crisis`;
            if (hitMandate && credIntact && safe && exemplar) performanceKey = `authentic_growth`;
            else if (hitMandate && credIntact && safe) performanceKey = `credible_campaign`;
            else if (hitMandate && (!safe || !credIntact)) performanceKey = `greenwashing_exposure`;
            else if (!hitMandate && credIntact && sales < this.MISS_FLOOR) performanceKey = `over_corrected`;
            else if (sales >= this.MISS_FLOOR) performanceKey = `grew_exposed`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (hitMandate && credIntact && safe) insights.push(window.mySimulation.t(`insight_authentic`));
            else if (ds.fined) insights.push(window.mySimulation.t(`insight_fined`));
            else if (hitMandate && !credIntact) insights.push(window.mySimulation.t(`insight_premium`));
            else if (sales < this.MISS_FLOOR && credIntact) insights.push(window.mySimulation.t(`insight_silence`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (cred < this.START_CRED - 18) insights.push(window.mySimulation.t(`insight_cliff`));
            if (risk >= 55) insights.push(window.mySimulation.t(`insight_risk`));
            if (sales < this.MISS_FLOOR) insights.push(window.mySimulation.t(`insight_downround`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (hitMandate && credIntact && safe && cred >= this.START_CRED) insights.push(window.mySimulation.t(`insight_grew_cred`));

            return {
                salesLift: sales,
                credibility: cred,
                gwRisk: risk,
                hitMandate: hitMandate,
                credIntact: credIntact,
                safe: safe,
                fined: ds.fined,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.fined) return window.mySimulation.t(`hint_fined`);
            if (ds.gwRisk >= 50) return window.mySimulation.t(`hint_risk`);
            if (ds.credibility < this.START_CRED - 18) return window.mySimulation.t(`hint_cred`);
            if (state.currentPeriod >= 3 && ds.salesLift < this.MISS_FLOOR) return window.mySimulation.t(`hint_behind`);
            if (ds.salesLift >= this.MANDATE - 5 && ds.credibility >= this.START_CRED - 8 && ds.gwRisk < 35) return window.mySimulation.t(`hint_strong`);
            return null;
        }

